// Landing-page content model. Two sources feed the same shape:
//   - hf-media.json  → Higgsfield's own landing media, hotlinked (review-only,
//                      generated by scripts; off unless the file says enabled)
//   - the fallback   → stills generated by this app + free-license clips
import raw from "./hf-media.json";
import { PRESETS, presetThumbUrl } from "./presets";
import { PRESET_CLIPS, PROJECT_CLIPS, GENJUTSU_CLIPS, FEATURE_CLIPS, clipUrl } from "./clips";

export interface FeatureCard { title: string; body: string; href: string; poster: string; video: string }
export interface EffectTile { id: string; name: string; poster: string; video: string }
export interface RowItem { poster: string; video?: string; author: string }
export interface Row { title: string; blurb: string; href: string; ratio: string; items: RowItem[] }
export interface Project { slug: string; title: string; poster: string; hls?: string; video?: string }
export interface Landing {
  source: "higgsfield" | "generated";
  feature: FeatureCard[];
  promo: { poster: string; video: string };
  effects: EffectTile[];
  genjutsu: string[];
  rows: Record<"seedance25" | "gptImage2" | "marketing" | "seedance2" | "soulCinema" | "soul2", Row>;
  projects: Project[];
  banners?: { supercomputer: Record<string, string>; canvas: Record<string, string>; photodump: Record<string, string> };
  moreFeatures: { label: string; href: string }[];
  footer: { title: string; links: string[] }[];
}

type HfJson = Partial<Landing> & { enabled?: boolean };

